let films,cinema,campaign,catalog,artMap,settings={...DEFAULT_SETTINGS},run=null,view='title',mapDisk=1,field=null,battle=null,currentStage=null,training=false,replay=false,battleOutcome=false;
let storyLines=[],storyIndex=0,storyDone=null,choicePending=false,hudAt=0,last=performance.now(),uiBusy=false,loading=false,keyboard=new Set,movePointers=new Map,missionBefore=null,rematch=false;
const modal=$('#modal'),renderer=new Renderer($('#world')),sound=new Soundscape();
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000);}
function show(html){$('#modal-body').innerHTML=html;if(!modal.open)modal.showModal();keyboard.clear();movePointers.clear();}
function closeModal(){modal.close();}
function dismissModal(){if(battle&&battle.state!=='active'){toast('結果画面のボタンから進んでください。');return;}closeModal();}
$('#close-modal').onclick=dismissModal;modal.addEventListener('cancel',e=>{if(battle&&battle.state!=='active')e.preventDefault();keyboard.clear();});modal.addEventListener('click',e=>{if(e.target===modal)dismissModal();});
function setView(name){view=name;for(const x of ['title','map','play'])$('#'+x+'-screen').hidden=x!==name;document.body.classList.toggle('in-play',name==='play');keyboard.clear();movePointers.clear();window.scrollTo(0,0);if(name==='play')requestAnimationFrame(()=>renderer.fit());}
const saveAuto=async()=>{if(!run||training||replay)return;try{run.updated=Date.now();if(view==='play'&&field)run.field=clone(field);await autosave(run);}catch(e){toast('自動保存に失敗しました。セーブ管理から書き出してください。');}};
function safe(fn){return async(...a)=>{try{await fn(...a);}catch(e){console.error(e);toast(e.message||'処理を完了できませんでした。');}};}
const heroByName=n=>HEROES.find(h=>h.name===n);
function openStory(lines,done){storyLines=(lines||[]).map(l=>Array.isArray(l)?{speaker:l[0],text:l[1]}:l);storyIndex=0;storyDone=done;keyboard.clear();movePointers.clear();if(!storyLines.length){done?.();return;}$('#story').hidden=false;drawStory();}
function drawStory(){const line=storyLines[storyIndex],h=heroByName(line.speaker);$('#story-speaker').textContent=line.speaker||currentStage?.location||'記憶';$('#story-text').textContent=line.text;$('#story-progress').textContent=(storyIndex+1)+' / '+storyLines.length;const p=$('#story-portrait');p.style.backgroundImage=h?'url(native/art/portrait-'+h.key+'.webp)':'none';p.textContent=h?'':line.speaker?.slice(0,1)||'◇';$('#story-next').innerHTML=storyIndex===storyLines.length-1?'進む <span>→</span>':'次へ <span>→</span>';}
$('#story-next').onclick=()=>{sound.play('ui');if(++storyIndex<storyLines.length)drawStory();else{$('#story').hidden=true;const f=storyDone;storyDone=null;f?.();}};
function enemySource(id){return catalog.enemies.find(e=>e.id===id)||{id,name:'魔物',image:''};}
function nativeArt(e,title=''){return enemyDesign(e,familyFor(e),title);}
function artStyle(e,title=''){const d=nativeArt(e,title);return 'background-image:url(native/art/'+d.sheet+'.webp);background-size:'+(d.cols*100)+'% '+(d.rows*100)+'%;background-position:'+(d.index%d.cols)/(d.cols-1)*100+'% '+Math.floor(d.index/d.cols)/(d.rows-1)*100+'%;'+(d.hue?'filter:hue-rotate('+d.hue+'deg);':'');}
function stageAllowed(s){return run&&s.disk<=run.disk&&(run.completed.includes(s.id)||campaign.stages[run.stage]?.id===s.id);}
function openMap(){rematch=false;battle=null;field=null;training=false;replay=false;$('#story').hidden=true;closeModal();mapDisk=run?.disk||1;renderMap();setView('map');sound.kind='field';}
function renderMap(){if(!run)return;const chapter=campaign.chapters.find(c=>c.disk===mapDisk);$('#disk-tabs').innerHTML=campaign.chapters.map(c=>'<button data-disk="'+c.disk+'" class="'+(c.disk===mapDisk?'active':'')+'"><b>Disk '+ROMAN[c.disk-1]+'</b><span>'+(c.disk>run.disk?'未解放':c.disk<run.disk?'踏破':'冒険中')+'</span></button>').join('');$('#disk-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{mapDisk=+b.dataset.disk;renderMap();});const lead=run.actors[1];$('#run-summary').innerHTML='<span>ザック Lv.'+lead.level+'</span><span>'+run.gold.toLocaleString()+' G</span><span>'+run.completed.length+' / 24 節</span>';$('#chapter-banner').style.backgroundImage='url(native/art/world-'+['starl','rift','coast'][mapDisk-1]+'.webp)';$('#chapter-banner').innerHTML='<div><p class="overline">DISK '+ROMAN[mapDisk-1]+' / CHAPTER '+mapDisk+'</p><h2>'+esc(chapter.title)+'</h2><p>'+esc(chapter.description)+'</p></div>';$('#stage-list').innerHTML=campaign.stages.filter(s=>s.disk===mapDisk).map(s=>{const done=run.completed.includes(s.id),current=campaign.stages[run.stage]?.id===s.id&&!done;return'<button class="stage-card '+(current?'current':'')+'" data-stage="'+s.id+'" '+(!stageAllowed(s)?'disabled':'')+'><span class="stage-n">'+String(s.order).padStart(2,'0')+'</span><span class="state">'+(done?'✓ 踏破':current?'現在地':'◇')+'</span><b>'+esc(s.title)+'</b><small>'+esc(s.location)+'</small></button>';}).join('');$('#stage-list').querySelectorAll('button').forEach(b=>b.onclick=()=>beginStage(campaign.stages.find(s=>s.id===b.dataset.stage),run.completed.includes(b.dataset.stage)));let gate='';if(mapDisk>run.disk)gate='<div class="chapter-gate"><h3>記録が、次の扉を開く。</h3><p>Disk '+run.disk+' の最後まで進み、章末セーブを残してください。</p><button id="gate-saves">保存した章末セーブを選ぶ</button></div>';else if(diskComplete(run,campaign)&&mapDisk===run.disk){gate='<div class="chapter-gate"><p class="overline">'+(run.disk===3?'CHRONICLE COMPLETE':'CHAPTER COMPLETE')+'</p><h3>'+ (run.disk===3?'帰ってこられる場所。':'次のDiskへ、約束をつなぐ。')+'</h3><p>'+(run.disk===3?'三つのDiskの物語を終えました。各地を再訪し、残された依頼を手伝えます。':'まず章末をセーブ。その保存データから次のDiskを始めます。元の記録は残ります。')+'</p><div class="button-row"><button id="seal-save" class="primary">章末をセーブ</button>'+(run.disk<3?'<button id="gate-saves">章末セーブから引き継ぐ →</button>':'<button id="ending-review">結末を読み返す</button>')+'</div></div>';}$('#chapter-gate').innerHTML=gate;$('#seal-save')?.addEventListener('click',()=>openSaves(true));$('#gate-saves')?.addEventListener('click',()=>openTransfers());$('#ending-review')?.addEventListener('click',()=>beginStage(campaign.stages.at(-1),true));}
$('#map-home').onclick=()=>{setView('title');};
$('#new-game').onclick=()=>{show('<p class="overline">A NEW CHRONICLE</p><h2>新しい旅をはじめる</h2><p>スタル町から、ザックの旅が始まります。手動セーブは残ります。進行中の旅は、先に保存しておくと安心です。</p><div class="button-row"><button id="begin-new" class="primary">旅立つ</button><button id="save-before-new">いまの記録を保存</button></div>');$('#begin-new').onclick=safe(async()=>{run=newRun();await autosave(run);closeModal();await sound.start(settings);openMap();beginStage(campaign.stages[0]);});$('#save-before-new').onclick=()=>run?openSaves():toast('進行中の記録はありません。');};
$('#continue').onclick=safe(async()=>{if(!run){const a=await getMeta('autosave');if(a)run=validateRun(a.run,campaign);}if(!run){$('#new-game').click();return;}await sound.start(settings);if(run.field?.stageId===campaign.stages[run.stage]?.id&&!run.completed.includes(run.field.stageId)){const s=campaign.stages[run.stage];startField(s,clone(run.field));}else {openMap();resumeFilms();}});
function makeField(stage){return{stageId:stage.id,x:75,y:0,face:1,moving:false,visited:[],encounter:0,hotspots:(stage.clues||[]).slice(0,3).map((c,i)=>({id:'clue-'+i,x:280+i*270,y:i%2*.18,label:c.title})).concat([{id:'gate',x:1170,y:0,label:stage.encounters.length?'先へ進む':'目的を果たす'}]),moveTo:null,gateStarted:false};}
function beginStage(stage,isReplay=false,filmShown=false){if(!isReplay&&stage.order===1&&!filmShown&&needsFilm('d'+stage.disk+'-opening')){playFilm('d'+stage.disk+'-opening',()=>beginStage(stage,false,true));return;}if(!stageAllowed(stage)&&!isReplay){toast('前の節を終えると進めます。');return;}replay=isReplay;training=false;missionBefore=clone(run);currentStage=stage;battle=null;field=null;closeModal();renderer.setStage(stage);$('#scene-location').textContent='DISK '+ROMAN[stage.disk-1]+' · '+stage.location;$('#scene-title').textContent=stage.title;$('#scene-mode').textContent='CHRONICLE';$('#objective').textContent=stage.objective;$('#field-controls').hidden=true;$('#battle-controls').hidden=true;$('#enemy-tabs').innerHTML='';$('#battle-notice').textContent='';$('#combat-cues').hidden=true;setView('play');openStory(stage.storyBefore,()=>startField(stage));}
function startField(stage,saved=null){currentStage=stage;battle=null;field=saved||makeField(stage);field.party=[...run.party];field.lastStep=0;document.body.classList.remove('in-battle');field.moveTo=null;field.moving=false;field.face??=1;field.gateStarted=false;renderer.setStage(stage);renderer.mode='field';$('#scene-location').textContent='DISK '+ROMAN[stage.disk-1]+' · '+stage.location;$('#scene-title').textContent=stage.title;$('#scene-mode').textContent='EXPLORE';$('#field-controls').hidden=false;$('#battle-controls').hidden=true;$('#field-tip').hidden=false;$('#enemy-tabs').innerHTML='';$('#battle-notice').textContent='';$('#combat-cues').hidden=true;setView('play');sound.kind='field';sound.setScene(stage.biome);updateFieldHud();saveAuto();}
function updateFieldHud(){if(!field)return;const clues=field.visited.filter(x=>x.startsWith('clue')).length;$('#objective').textContent=currentStage.objective+'　'+clues+'/3';const near=nearestHotspot();$('#nearby-label').textContent=near?near.label: '光の印へ進もう';$('#interact').textContent=near?(near.id==='gate'?'先へ進む →':field.visited.includes(near.id)?'もう一度読む':'調べる ◇'):'調べる ◇';$('#interact').disabled=!near;}
function nearestHotspot(){return field?.hotspots.find(h=>Math.abs(field.x-h.x)<105&&Math.abs(field.y-(h.y||0))<.7);}
$('#interact').onclick=()=>interact();
function interact(){if(!field||!$('#story').hidden||modal.open)return;const near=nearestHotspot();if(!near){toast('光る印へ近づいてください。');return;}field.moveTo=null;if(near.id==='gate'){if(field.visited.filter(x=>x.startsWith('clue')).length<3){toast('この場所の３つの手掛かりを確かめてから進もう。');return;}if(currentStage.storyChoice&&!run.choices[currentStage.id]&&!replay){openChoice(currentStage.storyChoice,()=>beginEncounter());return;}beginEncounter();return;}const i=+near.id.split('-')[1],clue=currentStage.clues[i];if(!field.visited.includes(near.id)){field.visited.push(near.id);renderer.particle(renderer.position('player').x,renderer.position('player').y-80,'#e7cf8f',25);sound.play('ui');}openStory([{speaker:clue.title,text:clue.text}],()=>{updateFieldHud();saveAuto();});}
function openChoice(choice,done){show('<p class="overline">A SMALL DECISION</p><h2>旅の途中で</h2><p>'+esc(choice.prompt)+'</p><div class="quest-options">'+choice.options.map((o,i)=>'<button class="choice-option" data-choice="'+i+'" style="display:block;width:100%;text-align:left;margin:10px 0">'+esc(o.text)+' →</button>').join('')+'</div>');$('#modal-body').querySelectorAll('[data-choice]').forEach(b=>b.onclick=safe(async()=>{const i=+b.dataset.choice,o=choice.options[i];run.choices[currentStage.id]=i+1;run.hope+=(o.effect?.bond||1);closeModal();openStory([{speaker:'旅の記憶',text:o.result}],()=>{saveAuto();done();});}));}
function beginEncounter(introShown=false){if(!field||loading)return;const encounter=currentStage.encounters[field.encounter];if(!encounter){finishStage();return;}if(encounter.storyBefore&&!introShown){openStory(encounter.storyBefore,()=>beginEncounter(true));return;}loading=true;document.body.classList.add('in-battle');field.gateStarted=true;saveAuto();battle=new Battle(run,currentStage,encounter,catalog,settings);battle.bond=Math.min(35,(run.hope||0)*3);battleOutcome=false;$('#field-controls').hidden=true;$('#battle-controls').hidden=false;$('#field-tip').hidden=true;$('#scene-mode').textContent=encounter.boss?'BOSS FIGHT':'BATTLE';$('#objective').textContent=encounter.title+'　'+(field.encounter+1)+'/'+currentStage.encounters.length;$('#enemy-tabs').innerHTML=battle.enemies.map((e,i)=>'<button data-target="'+i+'" class="'+(!i?'active':'')+'">'+esc(e.name)+'<span class="enemy-weak">弱点 '+ELEMENTS[e.weak]+'</span></button>').join('');$('#enemy-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{battle.target=+b.dataset.target;$('#enemy-tabs').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));});buildPartyHUD();sound.kind='battle';sound.setScene(currentStage.biome);sound.pad();$('#encounter-label').textContent=encounter.boss?'BOSS ENCOUNTER\n'+encounter.title:'ENCOUNTER';$('#combat-cues').hidden=false;$('#encounter-label').hidden=false;setTimeout(()=>{$('#encounter-label').hidden=true;loading=false;},950);updateBattleHUD();}
function buildPartyHUD(){if(!battle)return;$('#party-bar').innerHTML=battle.heroes.map(h=>'<button class="party-hud '+(h.id===battle.activeId?'active':'')+'" data-hero="'+h.id+'" aria-label="'+h.name+'を操作"><img src="native/art/portrait-'+h.key+'.webp" alt=""><span><b>'+h.name+' <small>Lv.'+h.level+'</small></b><span class="bar"><i data-hp></i></span><span class="bar sp-bar"><i data-sp></i></span><span class="hp-num" data-hp-num></span></span></button>').join('');$('#party-bar').querySelectorAll('button').forEach(b=>b.onclick=()=>{const h=battle.heroes.find(x=>x.id===+b.dataset.hero);if(h.hp<=0)return;battle.switchHero(h.id);updateBattleHUD();sound.play('ui');});}
function updateBattleHUD(){if(!battle)return;const h=battle.actor();if(!h)return;for(const el of $('#party-bar').querySelectorAll('button')){const p=battle.heroes.find(x=>x.id===+el.dataset.hero);el.classList.toggle('active',p.id===battle.activeId);el.classList.toggle('dead',p.hp<=0);el.querySelector('[data-hp]').style.width=p.hp/p.maxHp*100+'%';el.querySelector('[data-sp]').style.width=p.sp+'%';el.querySelector('[data-hp-num]').textContent=Math.ceil(p.hp)+' / '+p.maxHp+'　MP '+Math.floor(p.sp);}
 $('#skill-name').textContent=h.skill;$('#skill-cost').textContent='技力28 / ２';$('#potion-label').textContent='回復薬 ×'+run.potions;$('#bond-label').textContent=Math.floor(battle.bond)+'%';$('#bond-fill').style.height=battle.bond+'%';$('#ultimate').classList.toggle('ready',battle.bond>=100);$('#ultimate').disabled=battle.bond<100;for(const b of $$('.commands [data-action]')){const k=b.dataset.action,t=battle.cooldowns[k];b.disabled=t>.05||k==='skill'&&h.sp<28||k==='item'&&run.potions<1;const max={attack:.95,skill:4.2,guard:3.2,dodge:3.6,item:3}[k];b.querySelector('i').style.width=t/max*100+'%';}const selected=battle.enemy();if(selected){const next=intendedMove(selected);$('#enemy-technique').textContent=selected.stun>0?'BREAK — 今が好機':next.name+' まで '+Math.max(0,selected.intent).toFixed(1)+'秒';$('#enemy-advice').textContent=selected.stun>0?'攻撃と固有技を重ねよう':moveHint(next);$('#combat-cues').dataset.kind=next.kind;}$('#chain-hud').textContent=battle.relayUntil>battle.time?'RELAY READY · 固有技で追撃':battle.chain>1?battle.chain+' CHAIN · 切替で連携':'３連撃で崩す';const log=battle.messages.slice(0,2).map(m=>m.text).join('　/　');$('#battle-notice').textContent=log;for(const b of $('#enemy-tabs').querySelectorAll('button')){const e=battle.enemies[+b.dataset.target];b.disabled=e.hp<=0;b.classList.toggle('active',battle.enemy()===e);}}
function act(type){if(!battle||cinema?.active||modal.open||!$('#story').hidden||loading)return;const ok=battle.act(type);if(ok&&['guard','dodge'].includes(type))sound.play(type);updateBattleHUD();}
$$('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));$('#ultimate').onclick=()=>act('ultimate');
function battleEnd(){if(battleOutcome)return;battleOutcome=true;const won=battle.state==='victory';if(won){sound.play('victory');if(!training)persistReplayCollection();if(rematch){show('<p class="overline">BOSS RECORD UPDATED</p><h2>討伐記録を更新しました</h2><p>図鑑と最短討伐時間を保存しました。</p><button id="rematch-done" class="primary">ボス図鑑へ</button>');$('#rematch-done').onclick=async()=>{await leaveReplay();openCodex('bosses');};return;}if(training){show('<p class="overline">COMBAT TRIAL</p><div class="result-heading">VICTORY</div><p>予兆を読み、仲間と連携できました。訓練結果は本編の進行や所持品に影響しません。</p><div class="button-row"><button id="trial-again" class="primary">もう一度</button><button id="trial-exit">タイトルへ</button></div>');$('#trial-again').onclick=()=>startTraining();$('#trial-exit').onclick=()=>exitTraining();return;}field.encounter++;run.field=clone(field);saveAuto();const cleared=currentStage.encounters[field.encounter-1],next=currentStage.encounters[field.encounter];show('<p class="overline">ENCOUNTER CLEARED</p><div class="result-heading">VICTORY</div><div class="result-stats"><div><b>'+Math.round(battle.time)+'s</b><small>BATTLE TIME</small></div><div><b>'+battle.heroes.filter(h=>h.hp>0).length+'</b><small>仲間が生還</small></div><div><b>'+field.encounter+'/'+currentStage.encounters.length+'</b><small>この節の戦闘</small></div></div><p class="battle-score">最大 '+battle.chainPeak+' 連撃　/　完全防御 '+battle.perfects+' 回　/　回避 '+battle.dodges+' 回</p><p style="text-align:center">'+(next?'道が開いた。息を整え、次の場所へ進もう。':'この場所での戦いが終わった。仲間の言葉を聞こう。')+'</p><div class="button-row"><button id="after-battle" class="primary">'+(next?'次の遭遇へ →':'物語のつづきへ →')+'</button><button id="battle-camp">道具を補充する</button></div>');const proceed=()=>{closeModal();battle=null;const done=()=>next?beginEncounter():finishStage();cleared.storyAfter?openStory(cleared.storyAfter,done):done();};$('#after-battle').onclick=proceed;$('#battle-camp').onclick=()=>openCamp(proceed);}
 else showDefeat();}
function showDefeat(){show('<p class="overline">THE JOURNEY CONTINUES</p><h2>まだ、帰るには早い。</h2><p>この戦闘の最初から立て直せます。物語の進行と手動セーブは失われません。</p><div class="notice">赤い予兆の直前に防御するとダメージを防ぎます。大技には回避。技力が足りない時は仲間を切り替えてみましょう。</div><div class="button-row"><button id="retry-battle" class="primary">回復して再挑戦</button><button id="retry-story">物語重視の難易度にする</button><button id="retreat-map">冒険の記録へ</button></div>');$('#retry-battle').onclick=()=>{run.potions=Math.max(run.potions,3);closeModal();beginEncounter();};$('#retry-story').onclick=async()=>{settings.difficulty='story';await saveSettings();run.potions=Math.max(run.potions,5);closeModal();beginEncounter();};$('#retreat-map').onclick=async()=>{if(training)exitTraining();else if(replay)await leaveReplay();else openMap();};}
function finishStage(){battle=null;$('#combat-cues').hidden=true;document.body.classList.remove('in-battle');loading=false;$('#battle-controls').hidden=true;$('#field-controls').hidden=true;$('#scene-mode').textContent='CHRONICLE';openStory(currentStage.storyAfter,async()=>{if(replay){show('<p class="overline">MEMORY REVISITED</p><h2>あの日の旅を、もう一度。</h2><p>再訪を終えました。物語の進行・報酬・仲間の状態は変わりません。</p><button id="return-map" class="primary">冒険の記録へ</button>');run=mergeCollections(missionBefore,run);$('#return-map').onclick=openMap;return;}const oldLevels=Object.fromEntries(Object.entries(run.actors).map(([id,a])=>[id,a.level]));completeStage(run,currentStage,campaign);run.field=null;await autosave(run);renderMap();const recruited=(currentStage.rewards.unlockActors||[]).map(id=>HERO_BY_ID[id]?.name).filter(Boolean);const levelled=run.roster.filter(id=>run.actors[id].level>(oldLevels[id]||run.actors[id].level)).map(id=>HERO_BY_ID[id].name);show('<p class="overline">CHRONICLE '+String(currentStage.globalOrder).padStart(2,'0')+' COMPLETE</p><h2>'+esc(currentStage.title)+'</h2><div class="rewards">'+currentStage.rewards.gold+' G　/　経験値 '+currentStage.rewards.xp+'　/　強化素材 +2</div>'+(recruited.length?'<p class="gold" style="margin-top:18px">'+esc(recruited.join('・'))+' が仲間になりました。</p>':'')+(levelled.length?'<p>'+esc(levelled.join('・'))+' がレベルアップ。</p>':'')+'<p>'+(currentStage.chapterEnd?'このDiskの物語を終えました。冒険の記録で章末セーブを残してください。':'新しい道が開きました。野営で装備を整え、次の節へ。')+'</p><div class="button-row"><button id="return-map" class="primary">冒険の記録へ →</button><button id="save-complete">いまセーブする</button></div>');$('#return-map').onclick=openMap;$('#save-complete').onclick=()=>openSaves(currentStage.chapterEnd);if(currentStage.chapterEnd&&needsFilm('d'+currentStage.disk+'-ending')){const content=$('#modal-body').innerHTML;playFilm('d'+currentStage.disk+'-ending',()=>{show(content);$('#return-map').onclick=openMap;$('#save-complete').onclick=()=>openSaves(true);});}});}
let trainingBackup=null;
function startTraining(){if(!training)trainingBackup=run?clone(run):null;training=true;replay=false;run=newRun();for(const id of [2,3,5])addHero(run,id);for(const a of Object.values(run.actors))a.level=3;run.potions=99;currentStage={id:'trial',title:'仲間との戦闘訓練',location:'スタル町の外れ',biome:'forest',disk:1,order:2,globalOrder:2,objective:'攻撃・固有技・防御・回避を試そう',encounters:[{enemyIds:[132,133],boss:false,title:'訓練用の幻影'}]};field={stageId:'trial',encounter:0,visited:[],hotspots:[],x:0,y:0};closeModal();renderer.setStage(currentStage);$('#scene-title').textContent='戦闘訓練';$('#scene-location').textContent='COMBAT TRIAL / 本編の記録には影響しません';setView('play');sound.start(settings);beginEncounter();}
function exitTraining(){run=trainingBackup;trainingBackup=null;training=false;battle=null;field=null;closeModal();setView('title');}
$('#training').onclick=startTraining;
function pauseMenu(){if(battle&&battle.state!=='active'){toast('結果画面のボタンから進んでください。');return;}show('<p class="overline">PAUSED</p><h2>旅のひと休み</h2><p>メニューを開いている間、探索と戦闘は停止します。</p><div class="button-row"><button id="unpause" class="primary">ゲームへ戻る</button><button id="pause-settings">設定</button>'+(!training?'<button id="pause-save">セーブ</button><button id="pause-codex">モンスター図鑑</button>':'')+'<button id="pause-leave">'+(training?'訓練を終える':'冒険の記録へ')+'</button></div>');$('#unpause').onclick=closeModal;$('#pause-settings').onclick=openSettings;$('#pause-codex')?.addEventListener('click',()=>openCodex('enemies'));$('#pause-save')?.addEventListener('click',()=>openSaves());$('#pause-leave').onclick=async()=>{if(training){exitTraining();return;}if(replay){await leaveReplay();return;}await saveAuto();openMap();};}
$('#pause-game').onclick=pauseMenu;
async function openSaves(sealing=false){const all=(await slots()).sort((a,b)=>a.id-b.id);show('<p class="overline">SAVE YOUR CHRONICLE</p><h2>'+ (sealing?'章末の記録を残す':'セーブ・Disk引き継ぎ')+'</h2><p>この端末のブラウザに保存します。端末を替える前にファイルへ書き出してください。'+(battle?'戦闘中の保存は、その遭遇の開始前から再開します。':'')+'</p><div id="save-rows"></div><div class="button-row"><button id="export-current">いまの記録を書き出す</button><button id="import-save">ファイルを読み込む</button><button id="save-transfer">章末からDiskを引き継ぐ</button><button id="legacy-import">従来版の記録を変換</button></div><p class="notice">自動保存とは別に、手動で６枠まで記録できます。Disk移行には「章末をセーブ」で作った記録が必要です。サイトデータを消去すると端末内の保存も消えるため、書き出したファイルを保管してください。</p>');for(let id=1;id<=6;id++){const slot=all.find(s=>s.id===id),row=document.createElement('div');row.className='save-row';row.innerHTML='<div><b>記録 '+String(id).padStart(2,'0')+'　'+(slot?'Disk '+ROMAN[slot.run.disk-1]+' / Lv.'+slot.run.actors[1].level:'空いている枠')+'</b><small>'+(slot?new Date(slot.updated).toLocaleString('ja-JP')+' · '+slot.run.completed.length+'/24節':'新しい記録を保存できます')+'</small><small class="gold">'+(slot?.run.chapterSeals?.[slot.run.disk]?'章末セーブ':slot?'冒険の途中':'')+'</small></div><button class="load" '+(!slot?'disabled':'')+'>再開</button><button class="write" '+(!run||training||replay?'disabled':'')+'>'+(sealing?'章末を保存':'保存')+'</button>'+(slot?'<button class="download">書き出す</button>':'');row.querySelector('.load').onclick=safe(async()=>{run=validateRun(slot.run,campaign);await autosave(run);closeModal();await sound.start(settings);openMap();if(run.field?.stageId===campaign.stages[run.stage].id)startField(campaign.stages[run.stage],run.field);});row.querySelector('.write').onclick=safe(async()=>{let snapshot=clone(run);if(view==='play'&&field)snapshot.field=clone(field);if(sealing)snapshot=sealChapter(snapshot,campaign);const persist=async()=>{await saveSlot(id,snapshot,sealing?'章末の記録':'冒険の記録');if(sealing)run=clone(snapshot);await saveAuto();toast('記録 '+id+' に'+(sealing?'章末を':'')+'保存しました。');openSaves(sealing);};if(slot){show('<h2>記録 '+id+' を更新する</h2><p>この枠を現在の旅で上書きします。残したい記録は先に書き出してください。</p><div class="button-row"><button id="confirm-write" class="primary">この枠に保存する</button><button id="cancel-write">戻る</button></div>');$('#confirm-write').onclick=safe(persist);$('#cancel-write').onclick=()=>openSaves(sealing);}else await persist();});row.querySelector('.download')?.addEventListener('click',()=>downloadSave(slot.run));$('#save-rows').append(row);}$('#export-current').disabled=!run||training||replay;$('#export-current').onclick=()=>downloadSave(run);$('#import-save').onclick=()=>{$('#save-input').value='';$('#save-input').click();};$('#save-transfer').onclick=openTransfers;$('#legacy-import').onclick=openLegacy;}
function downloadBlob(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function downloadSave(value){if(!value)return;downloadBlob(JSON.stringify(wrapSave(value),null,2),'DoragonOut_ReChronicle_Disk'+value.disk+'.json');}
async function openTransfers(){const all=await slots();const ready=all.filter(s=>s.run.disk<3&&s.run.chapterSeals?.[s.run.disk]&&diskComplete(s.run,campaign));show('<p class="overline">CONTINUE ACROSS DISKS</p><h2>セーブが、旅をつなぐ。</h2><p>保存済みの章末データから次のDiskへ進みます。レベル・仲間・装備・道具・所持金・依頼の記録を引き継ぎ、移行元の記録も残します。</p><div id="transfer-rows"></div>'+(!ready.length?'<div class="notice">引き継げる章末セーブはまだありません。各Diskの８節を終え、「章末をセーブ」から保存してください。</div>':'')+'<div class="button-row"><button id="transfer-back">セーブ管理へ</button><button id="transfer-old">従来版 .lsd から変換</button></div>');ready.forEach(s=>{const b=document.createElement('button');b.className='save-row';b.style.width='100%';b.textContent='記録 '+s.id+' · Disk '+s.run.disk+' → '+(s.run.disk+1)+'　Lv.'+s.run.actors[1].level+'　引き継ぐ →';b.onclick=safe(async()=>{const persisted=await getSlot(s.id);run=transferChapter(persisted.run,campaign);await autosave(run);closeModal();openMap();toast('記録 '+s.id+' を残したまま Disk '+run.disk+' へ引き継ぎました。');playFilm('d'+run.disk+'-opening',()=>beginStage(campaign.stages[run.stage],false,true));});$('#transfer-rows').append(b);});$('#transfer-back').onclick=()=>openSaves();$('#transfer-old').onclick=openLegacy;}
$('#save-input').onchange=safe(async e=>{const f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024)throw Error('ファイルが大きすぎます。');let imported;if(f.name.toLowerCase().endsWith('.lsd'))imported=convertLegacy(new Uint8Array(await f.arrayBuffer()),campaign);else imported=unwrapSave(JSON.parse(await f.text()),campaign);await confirmImported(imported);});
async function confirmImported(imported){show('<p class="overline">RESTORE JOURNEY</p><h2>Disk '+imported.disk+' の記録</h2><p>ザック Lv.'+imported.actors[1].level+'　'+imported.gold.toLocaleString()+' G　'+imported.completed.length+'/24節</p>'+(imported.imported?'<div class="notice">原作の章末から、新しい戦闘と物語の進行へ変換します。レベル・所持金・装備と道具のID、元の .lsd データを保持します。戦闘能力はリメイク版の仕様で計算します。旧版の途中のイベントをそのまま再開する変換ではありません。</div>':'')+'<div class="button-row"><button id="accept-import" class="primary">この記録から続ける</button><button id="cancel-import">戻る</button></div>');$('#accept-import').onclick=safe(async()=>{run=validateRun(imported,campaign);await autosave(run);closeModal();openMap();toast('記録を読み込みました。手動セーブにも残せます。');});$('#cancel-import').onclick=()=>openSaves();}
async function openLegacy(){let old=[];try{old=await oldSaves();}catch{}show('<p class="overline">LEGACY SAVE CONVERSION</p><h2>従来版から、次の旅へ。</h2><p>Disk 1・2の章末、またはDisk 3クリア時の .lsd を、新しい進行へ変換できます。元のセーブは書き換えません。</p><div id="legacy-rows"></div><div class="button-row"><button id="legacy-file">.lsd ファイルを選ぶ</button><a href="./" class="legacy-link">原作マップ版・保存管理を開く ↗</a></div><p class="notice">途中のセーブは従来版で続け、章末で保存してから変換してください。</p>');for(const s of old){let converted;try{converted=convertLegacy(s.bytes,campaign);}catch{continue;}const b=document.createElement('button');b.className='save-row';b.style.width='100%';b.textContent='従来版 Disk '+s.disk+' / 枠'+s.slot+' · '+s.hero+' Lv.'+s.level+' → 変換';b.onclick=()=>confirmImported(converted);$('#legacy-rows').append(b);}if(!$('#legacy-rows').children.length)$('#legacy-rows').innerHTML='<p class="muted">このブラウザには変換できる従来版の章末セーブがありません。</p>';$('#legacy-file').onclick=()=>{$('#save-input').value='';$('#save-input').click();};}
async function saveSettings(){await setMeta('settings',settings);sound.apply(settings);document.body.classList.toggle('large-text',settings.largeText);if(battle)battle.settings={...settings};}
function openSettings(){show('<p class="overline">SETTINGS</p><h2>旅を、自分のペースで。</h2><div class="settings-grid"><label>難易度<select id="set-difficulty"><option value="story">物語重視</option><option value="normal">標準</option><option value="challenge">挑戦</option></select></label><label>戦闘速度<select id="set-speed"><option value="1">1.0倍</option><option value="1.25">1.25倍</option><option value="1.5">1.5倍</option></select></label><label>全体の音量<input id="set-volume" type="range" min="0" max="1" step=".05"></label><label>BGMの音量<input id="set-music" type="range" min="0" max=".7" step=".05"></label><label>光・粒子の量<select id="set-particles"><option value="0">なし</option><option value="0.5">少なめ</option><option value="1">標準</option></select></label><label class="toggle"><input type="checkbox" id="set-autoSupport">仲間の自動援護</label><label class="toggle"><input type="checkbox" id="set-effects">効果音</label><label class="toggle"><input type="checkbox" id="set-shake">画面の揺れ</label><label class="toggle"><input type="checkbox" id="set-largeText">会話を大きな文字に</label></div><div class="button-row"><button id="settings-done" class="primary">設定を保存</button><button id="fullscreen">全画面表示</button></div><p class="small muted">横向きでも縦向きでも操作できます。音声は画面の操作後に有効になります。</p>');for(const k of ['difficulty','speed','volume','music','particles'])$('#set-'+k).value=settings[k];for(const k of ['autoSupport','effects','shake','largeText'])$('#set-'+k).checked=settings[k];$('#settings-done').onclick=safe(async()=>{for(const k of ['difficulty','speed','volume','music','particles'])settings[k]=k==='difficulty'?$('#set-'+k).value:+$('#set-'+k).value;for(const k of ['autoSupport','effects','shake','largeText'])settings[k]=$('#set-'+k).checked;await saveSettings();closeModal();toast('設定を保存しました。');});$('#fullscreen').onclick=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch{toast('このブラウザでは全画面にできません。端末を横向きにしてみてください。');}};}
function openParty(){if(!run){toast('新しい旅を始めると仲間を編成できます。');return;}show('<p class="overline">COMPANIONS</p><h2>同じ道を歩く者たち。</h2><p>最大４人を編成できます。強化には素材と所持金を使います。外した仲間も経験を得ます。</p><p class="gold">'+run.gold+' G　/　強化素材 '+run.materials+'</p><div class="party-grid" id="party-cards"></div>');for(const h of HEROES){const unlocked=run.roster.includes(h.id),a=run.actors[h.id],st=unlocked?stats(run,h.id):null,selected=run.party.includes(h.id),card=document.createElement('article');card.className='hero-card '+(!unlocked?'unavailable':'');card.innerHTML='<img src="native/art/hero-'+h.key+'.webp" alt="'+h.name+'の新デザイン"><div><small>'+h.role+(unlocked?' · Lv.'+a.level:run.memorial?.includes(h.id)?' · 記憶の中に':' · 未加入')+'</small><h3>'+h.name+'</h3><p>'+h.skill+'<br>'+h.skillHint+'</p>'+(unlocked?'<p>HP '+st.maxHp+' / 攻撃 '+st.atk+'<br>武器 +'+a.weapon+' / 防具 +'+a.armor+'</p><button data-toggle>'+ (selected?'編成から外す':'パーティに加える')+'</button><button data-upgrade="weapon">武器強化 · '+(100+(a.weapon||0)*90)+' G</button><button data-upgrade="armor">防具強化 · '+(100+(a.armor||0)*90)+' G</button>':'<p>物語を進めると、この人物との記録が開かれます。</p>')+'</div>';card.querySelector('[data-toggle]')?.addEventListener('click',safe(async()=>{if(view==='play'){toast('編成は冒険の記録で行えます。');return;}if(selected){if(run.party.length===1){toast('少なくとも１人を編成してください。');return;}run.party=run.party.filter(id=>id!==h.id);}else{if(run.party.length>=4){toast('４人までです。先に誰かを外してください。');return;}run.party.push(h.id);}await saveAuto();openParty();}));card.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=safe(async()=>{const k=b.dataset.upgrade,cost=100+(a[k]||0)*90;if(a[k]>=10){toast('最大まで強化済みです。');return;}if(run.gold<cost||run.materials<2){toast('所持金と強化素材２個が必要です。');return;}run.gold-=cost;run.materials-=2;a[k]++;await saveAuto();openParty();toast('装備を強化しました。');}));$('#party-cards').append(card);}}
function openCamp(returnTo=null){if(!run){toast('旅を始めると野営できます。');return;}show('<p class="overline">CAMP & SUPPLIES</p><h2>夜を越える支度。</h2><p class="gold">'+run.gold+' G　/　回復薬 '+run.potions+' 個　/　強化素材 '+run.materials+' 個</p><div class="item-list"><article class="shop-item"><h3>回復薬</h3><p>戦闘中、最も傷ついた仲間のHPを55%回復します。</p><button id="buy-potion">１個購入 · 35 G</button></article><article class="shop-item"><h3>強化素材</h3><p>武器や防具を強化するための金属と革。１回の強化に２個使います。</p><button id="buy-material">１個購入 · 60 G</button></article></div><div class="button-row"><button id="camp-party">仲間・装備</button><button id="camp-quests">町の人の依頼</button><button id="camp-inventory">持ち物を見る</button>'+(returnTo?'<button id="camp-continue" class="primary">旅へ戻る →</button>':'')+'</div>');$('#buy-potion').onclick=safe(async()=>{if(run.gold<35){toast('所持金が足りません。');return;}run.gold-=35;run.potions++;await saveAuto();openCamp(returnTo);});$('#buy-material').onclick=safe(async()=>{if(run.gold<60){toast('所持金が足りません。');return;}run.gold-=60;run.materials++;await saveAuto();openCamp(returnTo);});$('#camp-party').onclick=openParty;$('#camp-quests').onclick=openQuests;$('#camp-inventory').onclick=openInventory;$('#camp-continue')?.addEventListener('click',returnTo);}
function openInventory(){const entries=Object.entries(run.inventory).filter(([,n])=>n>0);show('<p class="overline">INVENTORY</p><h2>旅を支えるもの。</h2><p>物語で得た品と、原作セーブから受け継いだ道具・装備の記録です。</p><div class="item-list">'+entries.map(([id,count])=>{const item=catalog.items.find(x=>x.id===+id);return'<article class="shop-item"><h3>'+esc(item?.name||'道具 #'+id)+' ×'+count+'</h3><p>'+esc(item?.description||'')+'</p></article>';}).join('')+'</div>'+(!entries.length?'<p class="muted">物語で得た品は、ここに記録されます。</p>':''));}
const questSteps={
 'water-for-stal':['上流の水門を閉める','水路の瓦礫を除く','濁りを確かめて水門を開く'],
 'creis-supplies':['必要な薬の数を聞く','工具と材料を分ける','足りない分を届ける'],
 'shelter-before-night':['高台の避難先を決める','怪我をした人から運ぶ','最後に人数を確かめる'],
 'albert-flowers':['仲間の記憶を聞く','名前を花札に書く','静かな場所へ花を供える'],
 'reunion-lights':['灯りの燃料を確かめる','帰り道の目印を置く','皆が揃ってから火を灯す']
};
function openQuests(){show('<p class="overline">LIVES ALONG THE ROAD</p><h2>誰かの日常を、取り戻す。</h2><p>物語を進めると、各地の生活を支える小さな依頼が開きます。</p>'+campaign.sideQuests.map(q=>{const done=run.sideQuests.includes(q.id),ok=run.completed.includes(q.afterStage);return'<article class="quest-row"><h3>'+esc(q.title)+'</h3><small class="gold">'+esc(q.location)+' / '+(done?'達成済み':ok?'受けられます':'物語で解放')+'</small><p>'+esc(q.text)+'</p><button data-quest="'+q.id+'" '+(!ok||done?'disabled':'')+'>'+ (done?'✓ 完了':'手を貸す →')+'</button></article>';}).join(''));$('#modal-body').querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>playQuest(campaign.sideQuests.find(q=>q.id===b.dataset.quest)));}
function playQuest(q){const answer=questSteps[q.id],options=[answer[2],answer[0],answer[1]],selected=[];function draw(message=''){show('<p class="overline">SIDE STORY / '+esc(q.location)+'</p><h2>'+esc(q.title)+'</h2><p>'+esc(q.objective)+'</p><div class="notice">'+(selected.length?selected.map((x,i)=>(i+1)+'. '+esc(x)).join('<br>'):'安全に手助けするための順番を選んでください。')+'</div><div class="button-row">'+options.map((s,i)=>'<button data-step="'+i+'" '+(selected.includes(s)?'disabled':'')+'>'+esc(s)+'</button>').join('')+'</div><p id="quest-feedback" class="gold">'+esc(message)+'</p><div class="button-row"><button id="quest-check" class="primary" '+(selected.length<3?'disabled':'')+'>この順番で手伝う</button><button id="quest-reset">選び直す</button></div>');$('#modal-body').querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{selected.push(options[+b.dataset.step]);draw();});$('#quest-reset').onclick=()=>{selected.length=0;draw();};$('#quest-check').onclick=safe(async()=>{if(selected.join('|')!==answer.join('|')){draw('まだ無理がありそうだ。準備を整え、人の安全を確かめてから仕上げよう。');return;}if(run.sideQuests.includes(q.id))return;run.sideQuests.push(q.id);run.gold+=q.reward.gold||0;run.materials+=2;run.hope++;for(const item of q.reward.items||[]){run.inventory[item.id]=(run.inventory[item.id]||0)+item.count;if(item.id===1||item.id===2)run.potions+=item.count;}await saveAuto();show('<p class="overline">SIDE STORY COMPLETE</p><h2>'+esc(q.title)+'</h2><p>大きな戦いの陰でも、明日の暮らしを続ける人がいる。手を貸した場所に、小さな安心が残った。</p><div class="rewards">'+q.reward.gold+' G / 強化素材 +2 / 仲間との信頼 +1</div><div class="button-row"><button id="quests-back" class="primary">依頼一覧へ</button></div>');$('#quests-back').onclick=openQuests;});}draw();}
function openJournal(){if(!run){toast('旅の記録は、冒険を始めると開きます。');return;}const completed=campaign.stages.filter(s=>run.completed.includes(s.id));show('<p class="overline">JOURNAL</p><h2>忘れないための、記録。</h2><p>クリアした節の結末と、選んだ行動を読み返せます。</p><div class="journal-list">'+completed.map(s=>'<article class="journal-entry"><small class="gold">DISK '+s.disk+' / '+String(s.order).padStart(2,'0')+'</small><h3>'+esc(s.title)+'</h3><p>'+esc(s.storyAfter.map(l=>l.speaker+'：'+l.text).join('\n'))+'</p>'+(run.choices[s.id]?'<p class="gold">選んだ行動：'+esc(s.storyChoice?.options[run.choices[s.id]-1]?.text||'')+'</p>':'')+'</article>').join('')+'</div>'+(!completed.length?'<p class="muted">最初の節を終えると、ここに記録されます。</p>':''));}
const familyLore=[
 '水分を含む体を伸縮させ、湿った地面を滑る。光る核の位置を見極めよう。','暗所の気流を読み、翼を畳んで急降下する。旋回の直後が反撃の好機。','群れで距離を詰める牙獣。飛びかかる前に重心が下がる。','硬い外殻と毒針を持つ。羽音が鋭くなったら距離を取ろう。','朽ちた骨を魔力がつないでいる。構えを崩せば動きが止まる。','古木や根に宿る存在。枝が地面を叩く大技には回避が有効。','岩の重みを力に変える巨体。動作は遅いが一撃が重い。','鎧に身を包み、間合いを測って斬り込む。攻撃直前の防御を狙おう。','薄霧のように漂い、魔力を集めて襲う。予兆と弱点を確かめよう。','翼で砂塵を巻き上げる竜種。羽ばたきからの大技に備えよう。','巨大な眼に魔力を集束する。視線が固定されたら守りを固めよう。','鱗で身を守り、長い尾と武器で攻撃する。手数に惑わされず構えを見よう。'];
const characterNotes={1:'焼けた故郷の記憶を背負う剣士。怒りを剣に託して歩き始めるが、人に話を聞くことも、剣を収めることも覚えていく。',2:'言葉を短く切るぶん、困った時には先に手を差し出す旅人。槍と冷静な判断で、ザックの危なっかしい歩みを支える。',3:'竜に強い関心を持つ召喚師。快活な振る舞いの陰で、仲間の傷には人一倍敏感。契約を命令ではなく対話として捉える。',4:'仕組みを知ろうとする研究者。傷んだ道具にも目を留め、暮らしに役立つ知恵を探す。戦場では錬成で相手の構えを解く。',5:'胸に残る記憶と言えなかった言葉を抱えた魔法使い。優しさだけでは守れないものがあると知り、炎を前へ向ける。',8:'里を守る忍者。声高に約束せず、道の安全や仲間の足音を確かめて行動する。軽い足取りと判断の速さが武器。'};
