 show('<p class="overline">FIELD RECORDS</p><h2>出会いを、記憶に刻む。</h2><div class="codex-tabs"><button id="codex-heroes" class="'+(tab==='heroes'?'active':'')+'">主要人物</button><button id="codex-enemies" class="'+(tab==='enemies'?'active':'')+'">モンスター</button><button id="codex-bosses" class="'+(tab==='bosses'?'active':'')+'">ボス</button></div><div id="codex-content"></div>');
 $('#codex-heroes').onclick=()=>openCodex('heroes');$('#codex-enemies').onclick=()=>openCodex('enemies');$('#codex-bosses').onclick=()=>openCodex('bosses');
